# -*- coding: utf-8 -*-
"""Portuguese, Dutch, and Italian narratives, translated from the English copy."""


def register(add):
    # ----- Portuguese -------------------------------------------------------
    add(1, "pt",
        title="Função da mão no AVC agudo: um ensaio randomizado de treino assistido por robô no Hospital NP Brain",
        desc="Ensaio randomizado com 30 pacientes no Hospital NP Brain: o treino da mão assistido por robô foi acrescentado à terapia neurodesenvolvimental. Os achados do Nine-Hole Peg, do ABILHAND e de Barthel são resultados do estudo.",
        lead="Depois de um AVC, a mão costuma voltar às tarefas do dia mais devagar do que a marcha: uma chávena, um botão ou um talher torna-se um obstáculo concreto. A janela aguda muda depressa, por isso o que se acrescenta aí precisa de uma comparação randomizada e não da impressão de um caso. Em 2026 a Scientific Reports publicou um ensaio randomizado do Hospital NP Brain, na Turquia, que acrescentou treino da mão assistido por um robô Syrebo à terapia neurodesenvolvimental convencional. O artigo relata ganhos maiores na destreza, nas atividades bimanuais e no autocuidado do que a terapia isolada. A amostra tem 30 pessoas, e a espasticidade não separou os grupos.",
        bg=[
            "A mão é difícil porque precisa de força, movimento fracionado e uso real. A marcha pode treinar-se como um único alvo; a mão tem de agarrar e largar numa postura instável. A terapia neurodesenvolvimental já é a base da reabilitação aguda, mas um terapeuta não pode repetir cada preensão sem fim, por isso a dose e a regularidade são difíceis de alargar.",
            "Uma luva robótica macia pode, em princípio, fornecer essas repetições sob supervisão. Os doentes agudos ainda estão a mudar. Saber se o dispositivo pode ser acrescentado com segurança, e se as pontuações funcionais se movem com ele, é uma pergunta controlada. Este ensaio trata dessa fase, em vez de repetir um estudo de fase crónica.",
        ],
        device="O artigo nomeia o dispositivo como uma mão robótica SYREBO. A fotografia mostra uma luva macia, uma consola e um tablet para o leitor ver o formato. Os pormenores do modelo pertencem ao artigo e ao protocolo clínico.",
        design="Comparação randomizada de centro único. Um grupo recebeu treino da mão assistido por robô mais terapia neurodesenvolvimental (NT). O grupo de controlo recebeu apenas NT. Os desfechos foram a destreza fina, as atividades diárias bimanuais e o autocuidado, não a força isolada.",
        sample="O Hospital NP Brain incluiu 30 pessoas na fase aguda e randomizou-as. As sessões assistidas foram três vezes por semana durante oito semanas. Também se recolheram medidas de espasticidade.",
        result="O artigo relata melhorias maiores no grupo assistido no Nine-Hole Peg Test, no questionário ABILHAND e no índice de Barthel. É um achado entre grupos nesta amostra. Não é uma velocidade de recuperação prometida. A espasticidade não mostrou diferença significativa entre grupos, portanto nem todas as medidas se afastaram.",
        sig=[
            "A parte útil é o momento: a prática assistida foi testada na fase aguda contra a terapia neurodesenvolvimental em curso, e não foi trazida de resultados de fase crónica. Três medidas funcionais a moverem-se em conjunto informam mais do que uma pontuação isolada.",
            "Trinta doentes randomizados só sustentam uma leitura cautelosa. O ensaio não responde ao uso prolongado em casa, e não mostra que cada subtipo de AVC siga o mesmo caminho. O clínico que trata a pessoa continua a definir o plano.",
        ],
        limit="Amostra pequena (n=30). Sem diferença significativa entre grupos na espasticidade. As alterações de pontuação são o relato do estudo, não uma promessa individual.")

    add(2, "pt",
        title="Função da mão após o AVC: um ECR em ocultação simples de uma luva robótica macia e terapia em espelho, com seguimento a 6 meses",
        desc="Journal of Rehabilitation Medicine, 2025: 49 participantes, luva robótica macia versus terapia em espelho, oito semanas mais seguimento a seis meses. Os valores de P entre grupos são o relato do artigo.",
        lead="A terapia em espelho usa a entrada visual para recrutar o lado afetado. Uma luva robótica macia usa um atuador flexível para repetir a abertura e o fecho. Qual mudança dura mais não se responde no último dia de treino. Um ensaio randomizado em ocultação simples de 2025 no Journal of Rehabilitation Medicine comparou as duas abordagens durante oito semanas e seguiu as pessoas até aos seis meses. O artigo relata ganhos entre grupos estatisticamente significativos a favor da luva no Box and Block Test, na força de preensão e no FMA-UE no fim do treino, e relata que esses ganhos do grupo da luva ainda estavam presentes aos seis meses.",
        bg=[
            "A pergunta que importa depois do treino da mão é se a mudança ainda está lá quando a pessoa volta para casa. A terapia em espelho é simples e depende da atenção ao membro refletido. Uma luva desloca a repetição para um atuador externo, com outra exigência de atenção e resistência. Ambos são métodos de reabilitação. Isto não é um ranking de marcas.",
            "Uma pontuação no último dia de treino pode confundir um estímulo breve com uma mudança estável. Uma comparação randomizada com uma visita aos seis meses é o que torna essa distinção possível.",
        ],
        device="A fotografia da coluna mostra uma montagem de treino em espelho E12. O dispositivo do estudo é o que o artigo especifica; a foto não é uma correspondência de modelo.",
        design="Randomização em ocultação simples de uma luva robótica macia contra terapia em espelho. Os desfechos foram a destreza de agarrar e largar (Box and Block), a força de preensão e o movimento do membro superior (FMA-UE), com uma visita seis meses após o treino.",
        sample="Quarenta e nove pessoas após AVC foram randomizadas. O treino durou oito semanas. O registo é NCT05898971.",
        result="No fim do treino o artigo relata diferenças entre grupos a favor da luva: Box and Block P=0,004, preensão P=0,011, FMA-UE P=0,021. Aos seis meses os ganhos do grupo da luva ainda estavam presentes. Esses valores de P descrevem esta amostra. Não atribuem um tamanho de recuperação a cada doente.",
        sig=[
            "A informação extra é o tempo. A diferença entre grupos não tinha desaparecido na visita de seguimento. Isso é mais útil na clínica do que um ranking no último dia de treino.",
            "Quarenta e nove pessoas continuam a ser um ensaio pequeno. Diferenças basais, o lado da lesão e a prática após a alta podem mover uma pontuação aos seis meses. O achado pertence a esta população e a este contraste.",
        ],
        limit="Amostra pequena (n=49). Os valores de P e a manutenção dos ganhos são o relato do estudo, não uma promessa de produto.")

    add(3, "pt",
        title="Negligência unilateral no AVC subagudo: comparação randomizada do treino em espelho robótico no SY-HRE12",
        desc="NeuroRehabilitation, 2025: 24 pessoas na fase subaguda, todas com o SY-HRE12. Modo espelho versus movimento passivo predefinido, 30 minutos, três vezes por semana, durante cinco semanas.",
        lead="Algumas pessoas na fase subaguda têm mais do que uma mão fraca. Também podem negligenciar um lado do espaço, e o humor pode ressentir-se. O treino em espelho robótico projeta a mão menos afetada sobre a afetada, de modo que a visão e o movimento chegam na mesma repetição. Um ensaio randomizado de 2025 na NeuroRehabilitation comparou duas formas de usar a mesma luva macia: a função de espelho e um modo passivo predefinido. O artigo relata uma vantagem do treino em espelho em desfechos relacionados com a negligência e a depressão. A amostra tem 24 pessoas.",
        bg=[
            "A negligência torna as pontuações difíceis de ler. O problema não é apenas que a mão não se levanta; a atenção a um lado do espaço está reduzida. Um espelho convencional pode sugerir que a mão afetada se move quando não se move. O espelho robótico tenta fazer a luva afetada mover-se com a outra mão, para que ver e fazer ocupem o mesmo ensaio.",
            "Se os grupos tivessem usado dispositivos diferentes, qualquer diferença poderia ser o hardware. Este ensaio deu o SY-HRE12 a ambos os grupos e mudou apenas o modo. A pergunta é como a luva foi acionada, não se havia uma máquina nova.",
        ],
        device="O artigo usou o SYREBO SY-HRE12. A fotografia mostra uma consola E12, uma luva motorizada e uma luva de espelho para o sistema ser reconhecível. O dispositivo do estudo é o SY-HRE12.",
        design="Comparação randomizada. Ambos os grupos usaram o SY-HRE12. Um grupo usou a função de espelho. O outro usou o movimento passivo predefinido. Os desfechos incluíram negligência unilateral, medidas relacionadas com a depressão e atividades diárias.",
        sample="Vinte e quatro pessoas na fase subaguda, 12 em cada grupo. As sessões duraram 30 minutos, três vezes por semana, durante cinco semanas.",
        result="Nesta amostra o artigo relata uma vantagem do treino em espelho robótico sobre o movimento passivo predefinido nos desfechos relacionados com a negligência e a depressão. É uma diferença entre dois modos de um mesmo dispositivo. Não significa que a luva trate a negligência ou a depressão. A condição de controlo não era uma caixa de espelho comum.",
        sig=[
            "A pergunta passa de «se usar uma luva» para «que modo da mesma luva». Para pessoas que também têm negligência e peso no humor, é uma pergunta clínica mais precisa.",
            "Vinte e quatro participantes só sustentam uma leitura cautelosa. O ensaio não testa o uso em casa sem supervisão, e não oferece uma mudança garantida da atenção ou do humor.",
        ],
        limit="Amostra pequena (12 por grupo). O modo de controlo foi o movimento passivo predefinido, não uma caixa de espelho. As diferenças são o relato do estudo.")

    add(4, "pt",
        title="Preensão e pontuações motoras após o AVC: um ensaio randomizado de luvas de treino robótico",
        desc="SPORT TK, 2025: 30 participantes. Diferenças médias relatadas: preensão 1,87 (IC 95% 0,39–3,35, P=0,015) e Fugl-Meyer 16,67 (IC 95% 3,9–29,4, P=0,012). Nenhum modelo é nomeado.",
        lead="Após um AVC, os clínicos muitas vezes dividem a mão em dois problemas práticos: se consegue agarrar e se consegue mover-se com controlo. Um ensaio randomizado de 2025 no SPORT TK-EuroAmerican Journal of Sport Sciences mediu ambos. O artigo relata diferenças médias entre grupos estatisticamente significativas a favor das luvas de treino robótico na preensão e na pontuação motora de Fugl-Meyer. Participaram trinta pessoas, e o artigo não nomeia um modelo comercial.",
        bg=[
            "Uma mudança na preensão não produz necessariamente um movimento utilizável, e uma pontuação motora mais alta não significa que uma pessoa consiga levantar uma chávena. Medir força e movimento na mesma comparação randomizada evita publicar apenas o mais favorável dos dois.",
            "Os artigos sobre luvas muitas vezes omitem o modelo. Sem modelo, um resultado não pode ser copiado para uma ficha de produto. Este resumo fica, portanto, nos contrastes que o artigo realmente dá.",
        ],
        device="",
        design="Comparação randomizada da prática com luva de treino robótico contra uma condição de controlo. Os desfechos partilhados foram a preensão e a pontuação motora de Fugl-Meyer, relatadas como diferenças médias com intervalos de confiança de 95%.",
        sample="Trinta pessoas após AVC, 15 em cada grupo. O artigo não identifica um modelo comercializado. A fotografia genérica da luva é uma ilustração, não uma identificação do dispositivo.",
        result="As diferenças médias entre grupos relatadas são preensão 1,87 (IC 95% 0,39 a 3,35, P=0,015) e Fugl-Meyer 16,67 (IC 95% 3,9 a 29,4, P=0,012). Uma diferença média não é o ganho de cada pessoa. O intervalo da pontuação motora é largo, que é o aspeto de uma amostra pequena quando a estimativa é imprecisa.",
        sig=[
            "Publicar a diferença e o intervalo é mais utilizável do que a frase «melhor do que o controlo». A direção é visível, e a incerteza também.",
            "Como nenhum modelo é nomeado, o resultado não pode ser recontado como uma especificação ou uma indicação de uma luva Syrebo em particular. Trinta pessoas também deixam espaço para ruído de amostragem.",
        ],
        limit="Amostra pequena (n=30). Nenhum modelo é identificado, e a foto não é uma correspondência. As diferenças médias e os valores de P são as estatísticas do estudo.")

    add(5, "pt",
        title="Função da mão na fase subaguda precoce: um ECR piloto em ocultação simples do SY-HR03E da equipa de Huashan",
        desc="ECR piloto em ocultação simples na BioMedical Engineering OnLine: 20 doentes internados, SY-HR03E, quatro semanas. O artigo relata conclusão completa, ausência de eventos adversos e sinais preliminares nas pontuações da mão e nas atividades diárias.",
        lead="Na fase subaguda precoce a primeira pergunta não é quantos pontos uma pontuação poderia subir. É se as sessões podem ser concluídas e se são seguras. Uma equipa liderada pelo professor Jia Jie, no Hospital Huashan da Universidade Fudan, publicou na BioMedical Engineering OnLine um ensaio piloto randomizado em ocultação simples sobre o Syrebo SY-HR03E para a reabilitação da mão nessa janela. O artigo relata que os 20 participantes concluíram quatro semanas, sem desistências e sem eventos adversos. As pontuações da mão melhoraram em ambos os grupos, com uma mudança maior no grupo da luva. Uma mudança intragrupo nas atividades diárias atingiu significância estatística no grupo da luva.",
        bg=[
            "O braço e a mão costumam recuperar mais tarde do que a marcha. Comer, vestir-se e lavar-se dependem de um movimento fracionado dos dedos, não de um único número de força. A terapia convencional da mão ajuda, mas o número de repetições que um terapeuta consegue dar é limitado, e o mesmo movimento é difícil de repetir à beira do leito.",
            "Uma luva pneumática pode fletir e estender os dedos com pouca massa sobre a mão, e por isso se discute o uso à beira do leito. As pessoas na fase subaguda precoce também recuperam de forma espontânea. Qualquer «efeito preliminar» tem de ser lido sobre esse fundo. Um ensaio piloto randomizado serve para mostrar que um protocolo é viável e para deixar um sinal para um estudo maior. Não substitui um ensaio confirmatório.",
        ],
        device="O artigo descreve o SY-HR03E como uma luva macia comercial mais um controlador de mesa. A massa relatada é de cerca de 3,5 kg para o sistema e cerca de 110 g para a luva. Foles pneumáticos no dorso da mão assistem a flexão e a extensão. Sensores de pressão observam a mudança produzida quando a pessoa tenta mover-se; acima de um limiar predefinido de 0,7 kPa o controlador trata essa mudança como intenção de movimento e insufla ou esvazia. O modo pretendido é a assistência ativa, não um arrasto totalmente passivo.",
        design="Randomização piloto em ocultação simples. O grupo robótico acrescentou abertura e fecho assistidos pela luva à reabilitação padrão. O grupo convencional recebeu terapia tradicional da mão com a mesma duração de sessão. Ambos os grupos receberam também uma hora por dia de reabilitação padrão. Um terapeuta supervisionou a postura. Registo: ChiCTR2000034614.",
        sample="Vinte doentes internados, de 7 dias a 3 meses após o início, 10 em cada grupo. As sessões com luva foram de 30 minutos por dia, cinco dias por semana, durante quatro semanas. Cada abertura-fecho foi mantida cerca de três segundos. As afiliações dos autores incluem a equipa clínica e, como o artigo declara, a Shanghai Siyi Intelligent Technology. Essa relação faz parte da leitura.",
        result="O artigo relata que as 20 pessoas completaram quatro semanas, sem desistências e sem eventos adversos. As pontuações de Fugl-Meyer da mão melhoraram em ambos os grupos, com uma melhoria maior no grupo robótico. No índice de Barthel modificado, apenas a mudança intragrupo do grupo robótico é relatada como estatisticamente significativa (p<0,001); a mudança intragrupo do grupo convencional não o é. O estádio de Brunnstrom da mão também mostrou uma mudança intragrupo significativa apenas no grupo robótico. Num piloto de 10 contra 10, um valor de P intragrupo é um sinal, não evidência de que a função diária vá subir nos doentes em geral.",
        sig=[
            "Muitos estudos de luvas macias incluem pessoas na fase crónica. Este piloto desloca a pergunta de viabilidade e segurança para a janela de 7 dias a 3 meses. Não antecipa afirmações de eficácia da fase crónica.",
            "As pontuações da mão e as de atividade diária não tomaram a mesma forma estatística: o artigo relata uma mudança intragrupo significativa de Barthel apenas no grupo da luva. Essa separação merece ser testada de novo. Não é a afirmação de que as atividades da vida diária foram resolvidas. Uma luva de 110 g e a deteção de intenção tornam possível falar do uso à beira do leito e, mais tarde, em casa. Este estudo foi feito com doentes internados.",
        ],
        limit="Randomização piloto, 10 por grupo. Os sinais preliminares precisam de uma amostra maior. O valor de P é o relato do artigo para esse desfecho. Uma afiliação relacionada com o dispositivo é declarada e deve ser ponderada.")

    add(6, "pt",
        title="Compromisso da mão com padrão de estase de fleuma: um estudo de quatro braços e 200 pessoas de uma luva mais eletroacupuntura",
        desc="Journal of Hunan University of Chinese Medicine: 200 participantes, quatro braços. As taxas de eficácia total relatadas foram 88%, 76%, 77,6% e 70,8%. Esses números são o composto do estudo, não uma taxa de produto.",
        lead="Colocar uma luva robótica e eletroacupuntura no mesmo plano é uma escolha integrativa concreta, e o resultado tem de ficar ligado ao braço que o produziu. Um estudo de quatro braços de 2022 no Journal of Hunan University of Chinese Medicine incluiu 200 pessoas com compromisso da mão após AVC do padrão phlegm-stasis blocking collaterals e comparou luva mais eletroacupuntura, luva isolada, eletroacupuntura isolada e reabilitação habitual. As «taxas de eficácia total» próprias do artigo são 88%, 76%, 77,6% e 70,8%. Esse composto é o resumo dos autores. Não é uma taxa de eficácia de produto.",
        bg=[
            "Sob este diagnóstico de padrão, os percursos muitas vezes combinam reabilitação moderna e eletroacupuntura. Um desenho de quatro braços pode mostrar a combinação, o dispositivo isolado, a acupuntura isolada e o cuidado habitual na mesma escala, em vez de uma história antes-depois sem contraste.",
            "Uma taxa de eficácia total reduz vários juízos a uma percentagem. Serve para um contraste grosseiro e não serve como a mudança de uma pessoa numa escala com nome. Não pode ser citada como «a eficácia da luva é 88%».",
        ],
        device="",
        design="Quatro braços: luva robótica mais eletroacupuntura, luva isolada, eletroacupuntura isolada e reabilitação habitual. O desfecho discutido aqui é a taxa de eficácia total do artigo. As afiliações incluem a Shanghai Siyi Intelligent Technology, com Yin Ganggang como coautor. Essa declaração permanece na leitura.",
        sample="Duzentas pessoas com compromisso da mão após AVC no padrão phlegm-stasis blocking collaterals. É a maior amostra da coluna. O artigo não nomeia um modelo que possa ser emparelhado com um produto atual, e a fotografia genérica não é esse emparelhamento.",
        result="As taxas de eficácia total relatadas são 88% para luva mais eletroacupuntura, 76% para a luva isolada, 77,6% para a eletroacupuntura isolada e 70,8% para a reabilitação habitual. Um composto mais alto no braço combinado significa apenas que, pela regra deste estudo, esse braço pontuou mais. Não atribui 88% à luva, e 76% não é uma taxa de produto. Os números da luva isolada e da eletroacupuntura isolada ficam próximos, o que também argumenta contra explicar todo o padrão por um único componente.",
        sig=[
            "Duzentas pessoas e quatro braços dão um composto comparável, não uma percentagem para uma página de produto. Lidas como taxa de eficácia total, as diferenças entre combinação, modalidades isoladas e cuidado habitual são limitadas.",
            "O artigo, tal como aqui se resume, não fornece as mesmas diferenças médias dos outros ensaios da coluna. Até essas escalas estarem na mesa, o estudo trata de como os componentes foram combinados, não de quantos pontos uma pontuação da mão vai subir.",
        ],
        limit="As percentagens são as taxas de eficácia total próprias do estudo. O braço combinado não pode ser atribuído à luva nem à eletroacupuntura isoladamente. Nenhum modelo é nomeado.")

    add(7, "pt",
        title="Reabilitação da mão após enfarte da artéria cerebral média: o caso de uma doente de 66 anos",
        desc="Caso clínico na Cureus: uma mulher de 66 anos com enfarte bilateral do território da ACM recebeu um programa de luva Syrebo sob supervisão clínica. Um único caso não é um resultado geral.",
        lead="Um ensaio randomizado descreve uma diferença média. Um caso clínico descreve como a reabilitação foi organizada para uma pessoa. Em 2024, na Cureus, Sharma e colegas relataram uma mulher de 66 anos com enfarte nos territórios da artéria cerebral média que recebeu neurofisioterapia construída em torno de um programa de luva Syrebo. O relatório segue o curso da observação e da mudança funcional. É um caso, e não se generaliza.",
        bg=[
            "Um enfarte deste território costuma afetar o braço e a mão juntamente com a linguagem ou a cognição, por isso o plano é mais do que uma mão fraca. As famílias costumam precisar de saber quando a prática da luva se situou dentro da fisioterapia, e quem a supervisionou, mais do que uma percentagem.",
            "Um caso clínico pode escrever essa sequência. Não tem um controlo paralelo, por isso qualquer mudança antes-depois mistura a recuperação espontânea, o cuidado habitual e a luva. Essas peças não podem ser separadas.",
        ],
        device="O artigo discute um programa de luva Syrebo e não nomeia um modelo. A fotografia da luva e da consola é a figura 2 desse relatório de acesso aberto (CC BY 4.0), mostrada no excerto no topo. Não é uma figura de outra revisão.",
        design="Relato de um único caso, não um ensaio randomizado. Depois de a pessoa estar medicamente estável, os clínicos aplicaram neurofisioterapia que incluía o programa de luva Syrebo.",
        sample="Uma mulher de 66 anos com enfarte bilateral do território da ACM. O relatório regista observações e mudança funcional. Não fornece estatísticas entre grupos.",
        result="O valor do relatório é o curso dos cuidados, não uma taxa de melhoria. Mostra como uma luva macia foi colocada na reabilitação de uma pessoa com um enfarte grave, sob supervisão profissional. Uma mudança num único caso não é um grau de recuperação prometido.",
        sig=[
            "Numa coluna feita sobretudo de ensaios randomizados, um caso clínico está aqui para mostrar como um programa foi usado com uma pessoa. Preenche uma lacuna narrativa. Não eleva o nível de evidência.",
            "Um caso não pode estimar a frequência de eventos adversos, e não pode dizer se a fase aguda, subaguda ou crónica é a mais adequada. Essas perguntas ficam nos estudos controlados.",
        ],
        limit="Caso único. Não é um efeito geral. A mudança funcional não pode ser atribuída só à luva.")

    add(8, "pt",
        title="Compromisso do membro superior após o AVC: um estudo randomizado de 60 pessoas sobre terapia em espelho inovadora",
        desc="New Medicine, 2024: 60 pessoas, quatro semanas. O artigo relata ganhos maiores no FMA-UE, no FMA-WH e no índice de Barthel modificado com a terapia em espelho inovadora do que com a terapia em espelho convencional.",
        lead="A terapia em espelho convencional usa um espelho para sugerir que a mão afetada se move. A versão inovadora pede a uma luva robótica que conduza a mão afetada pela mesma ação que o espelho mostra, de modo que ver e fazer partilhem a sessão. Em 2024 a New Medicine publicou um estudo randomizado de Chen e colegas que comparou as duas versões em 60 pessoas durante quatro semanas. O artigo relata ganhos maiores da terapia em espelho inovadora no movimento do membro superior, no movimento do punho e da mão e nas atividades diárias.",
        bg=[
            "A terapia em espelho tem um limite conhecido: se a mão afetada não se move, a sugestão visual não tem uma entrada motora emparelhada. Ligar a flexão e a extensão assistidas à tarefa do espelho é uma tentativa de o lado afetado completar de facto um movimento dentro de uma amplitude que o terapeuta define.",
            "Saber se essa mudança aparece nas pontuações tem de ser testado contra a terapia em espelho convencional, não contra não fazer nada. Sessenta pessoas, divididas ao meio, são um tamanho randomizado preliminar.",
        ],
        device="Uma imagem de treino na página da revista mostra uma marca Yisheng (羿生). A coluna liga essa marca ao SY-HR08E dos materiais oficiais e mostra uma fotografia de produto com ecrã, consola e luva. A ligação é uma nota de identificação, não uma afirmação de modelo impressa como registo do ensaio.",
        design="Alocação por números aleatórios. A terapia em espelho inovadora, que combina uma tarefa de espelho com uma luva robótica, foi comparada com a terapia em espelho convencional. Os desfechos incluíram FMA-UE, FMA-WH e o índice de Barthel modificado.",
        sample="Sessenta pessoas com compromisso do membro superior após AVC, 30 em cada grupo, durante quatro semanas.",
        result="O artigo relata maior melhoria da terapia em espelho inovadora no FMA-UE, no FMA-WH e no índice de Barthel modificado. É a descrição entre grupos do estudo. As médias e os valores de P não são recalculados nesta página; enquanto a página da revista ainda é verificada, esses números ficam no artigo.",
        sig=[
            "A pergunta é se acrescentar um movimento assistido que corresponde ao espelho muda as pontuações em relação ao espelho isolado. Sessenta pessoas fornecem um contraste preliminar, não uma prova de programa domiciliário.",
            "Ligar a imagem da revista ao SY-HR08E só ajuda o leitor a reconhecer o dispositivo. Saber se a diferença de pontuação é estável espera uma verificação independente dos números completos.",
        ],
        limit="Trinta pessoas por grupo. As diferenças seguem o artigo. As médias e os valores de P não são recalculados aqui. A ligação do modelo é uma verificação entre a figura da revista e os materiais oficiais.")

    add(9, "pt",
        title="Hemiparesia esquerda após enfarte da ACM: um registo de estimulação farádica mais uma mão robótica",
        desc="Caso no IJPRCP: um homem de 60 anos com hemiparesia esquerda iniciou estimulação farádica mais o Syrebo C12 cerca de três meses após o AVC, cinco vezes por semana durante quatro semanas. Um caso combinado não é atribuído a nenhum dos componentes.",
        lead="Uma mão hemiparética recebe por vezes duas entradas ao mesmo tempo: estimulação elétrica dirigida ao músculo, e uma mão robótica para abrir e fechar os dedos. Um caso de 2025 no International Journal of Physiotherapy Research and Clinical Practice regista quatro semanas de estimulação farádica mais um Syrebo C12 num homem com hemiparesia esquerda. É o registo de um plano combinado, não um ensaio de eficácia de qualquer das peças.",
        bg=[
            "Meses após o AVC, a mudança da mão costuma ser mais lenta, e os clínicos por vezes acrescentam estimulação ou assistência externa à prática comum. Uma vez usadas as duas, uma mudança antes-depois não pode ser entregue de forma limpa a nenhuma delas.",
            "O relatório continua a ser útil. Indica quando o plano começou, com que frequência decorreu e que dispositivo estava na sala. Não dá uma taxa, e não dá uma diferença contra um controlo.",
        ],
        device="O dispositivo robótico do relatório é o Syrebo C12. A fotografia é um recorte da página oficial de produto do C12 para que a consola e a luva sejam reconhecíveis. Não acrescenta especificações que o artigo omitiu.",
        design="Uma intervenção combinada única: estimulação farádica em conjunto com a prática da mão robótica Syrebo C12. Não há um grupo de controlo paralelo.",
        sample="Um homem de 60 anos com hemiparesia esquerda. O plano começou 3 meses e 2 semanas após o AVC, cinco vezes por semana, durante quatro semanas.",
        result="Esta página não reimprime pontuações funcionais que não tenham sido verificadas contra o artigo para a coluna. O que está claro é a organização: estimulação e prática robótica foram usadas em conjunto, por isso uma mudança não pode ser escrita como o efeito do C12 isolado ou da estimulação isolada.",
        sig=[
            "O registo acrescenta um calendário concreto: cerca de três meses após o AVC, cinco sessões por semana, duas modalidades em conjunto. Não eleva o nível de evidência.",
            "Um caso de hemiparesia esquerda após enfarte da ACM não representa outras lesões nem outros tempos desde o início.",
        ],
        limit="Caso combinado único. A mudança não é atribuída ao C12 nem à estimulação, e não é um efeito geral.")

    add(10, "pt",
        title="Uma ortótese macia de punho e mão: conceção e avaliação preliminar na Wearable Technologies",
        desc="Ledoux e Barth relatam a sua própria ortótese de punho e mão impressa em 3D na Wearable Technologies. Esta nota fica nesse artigo de conceção. Não classifica produtos comerciais e não é um ensaio de eficácia.",
        lead="Em 2024 a Wearable Technologies, da Cambridge University Press, publicou um artigo de conceção de Ledoux e Barth, na Universidade Vanderbilt. O dispositivo que construíram e avaliaram de forma preliminar é a sua própria ortótese de preensão de punho e mão impressa em 3D. O artigo menciona estruturas macias comerciais ao discutir mãos vestíveis. Esta coluna não transforma essa discussão num ranking, e não trata o artigo como evidência de eficácia da Syrebo.",
        bg=[
            "Um dispositivo de mão que sai da sala de terapia tem de responder ao peso, ao perfil e a se uma pessoa o consegue vestir. Os artigos de conceção costumam enunciar essas restrições e depois descrever um protótipo. Não relatam primeiro um ensaio funcional multicêntrico. Ler um artigo de conceção como um artigo de eficácia inventa desfechos clínicos que não foram medidos.",
            "Uma estrutura macia e um exoesqueleto rígido respondem a problemas de engenharia diferentes. A macieza é uma forma de reduzir o perfil. Falar de mudança funcional continua a exigir um estudo em pessoas próprio.",
        ],
        device="O excerto no topo é a primeira página de acesso aberto (CC BY 4.0), não uma tabela de comparação. A fotografia de produto mostra um sistema clínico de luva Syrebo. Não é uma figura desta experiência.",
        design="Conceção, modelação e avaliação preliminar da ortótese impressa em 3D dos próprios autores. O artigo não é um ensaio randomizado da Syrebo nem uma comparação de eficácia entre dispositivos comercializados.",
        sample="A parte com pessoas é um olhar preliminar sobre o protótipo dos autores. O seu tamanho e as suas tarefas são os do artigo. Não é reescrita aqui como uma coorte Syrebo.",
        result="Esta página não cita adjetivos comerciais e não lista outras marcas. O que fica é que o artigo é um estudo de conceção de acesso aberto sobre uma estrutura macia e vestível. A palavra «presumably» dos autores marca o conforto como algo que não trataram como um desfecho medido.",
        sig=[
            "O artigo está na coluna para que um estudo de conceção permaneça distinto de um ensaio de eficácia. Saber se uma estrutura macia torna um dispositivo mais fácil de usar no dia a dia é um estudo de uso e um estudo funcional, em separado.",
            "O acesso aberto permite ao leitor verificar a redação. O sentido de verificar é impedir que uma presunção se torne conclusão, não eleger o produto mais leve.",
        ],
        limit="Não é um ensaio de eficácia da Syrebo, nem um ranking de produtos. A fonte matiza o conforto com «presumably». O recorte da primeira página não inclui uma tabela de comparação.")

    add(11, "pt",
        title="Robôs de dedos pensados para casa: uma nota de desenvolvimento no Journal of the Robotics Society of Japan",
        desc="Um artigo de 2023 do Journal of the Robotics Society of Japan discute robôs de dedos para uso domiciliário na hemiparesia e nomeia a Syrebo entre os poucos exemplos comercializados. Não é um ensaio clínico.",
        lead="A reabilitação da mão em casa é discutida há anos. Os exemplos comercializados na literatura da sociedade continuam a ser poucos. Em 2023 o Journal of the Robotics Society of Japan publicou um artigo de Furudate e colegas sobre um robô de reabilitação dos dedos pensado para o uso em casa após hemiparesia, e sobre desenvolvê-lo com clínicos. Os autores notam que os casos comercializados de uso em casa continuam raros, e nomeiam a luva de mão Syrebo como um desses casos. O artigo é uma nota de desenvolvimento e colaboração, não um ensaio de eficácia.",
        bg=[
            "Entre a enfermaria e a casa estão o vestir o dispositivo, os limites de segurança e o uso quando não há terapeuta na sala. Os artigos de engenharia colocam essas restrições dentro do trabalho com clínicos. Ser nomeado significa que os autores escolheram este produto como exemplo. Não significa que a sociedade tenha feito um estudo controlado.",
            "«Poucos foram comercializados» é também um limite. Lê-lo como «a reabilitação em casa já está geralmente disponível» transforma um exemplo numa afirmação epidemiológica.",
        ],
        device="O artigo não imprime uma fotografia da luva. A imagem da luva e da consola nesta coluna é a figura 2 do caso da Cureus de 2024 de Sharma e colegas (CC BY 4.0). A legenda diz isso. Não é a figura original do artigo da sociedade japonesa.",
        design="Artigo de desenvolvimento numa revista de sociedade, sobre robôs de dedos para uso em casa e sobre o trabalho com clínicos. Não há randomização nem comparação funcional entre grupos.",
        sample="Não se aplica um tamanho de amostra clínico. O artigo discute um caminho para um produto, não resultados numa coorte.",
        result="O enunciado, tal como é usado aqui, é que os robôs de dedos comercializados orientados para casa continuam a ser poucos, e que a Syrebo é um exemplo que os autores nomeiam. A coluna mantém esse âmbito. Não é reescrito como eficácia, como um lugar de mercado ou como a promessa de que o treino em casa será concluído.",
        sig=[
            "O valor da nota é que o uso em casa é tratado como um problema de engenharia definido com clínicos. Um exemplo comercializado mostra que um dispositivo passou do protótipo ao produto.",
            "Saber se pode ser usado de forma segura e repetida em casa continua a depender da indicação, da supervisão e de estudos clínicos separados. O artigo da sociedade não fornece esses dados.",
        ],
        limit="Não é um ensaio clínico da Syrebo. A fonte sublinha que os exemplos comercializados continuam poucos. A fotografia vem de outro caso de acesso aberto.")

    # ----- Dutch ------------------------------------------------------------
    add(1, "nl",
        title="Handfunctie bij een acuut CVA: een gerandomiseerde studie naar robotondersteunde training in het NP Brain Hospital",
        desc="Gerandomiseerde studie met 30 patiënten in het NP Brain Hospital: robotondersteunde handtraining werd toegevoegd aan neurodevelopmental therapy. De bevindingen op de Nine-Hole Peg Test, ABILHAND en Barthel zijn studieresultaten.",
        lead="Na een CVA keert de hand vaak trager terug naar dagelijkse taken dan het lopen: een kopje, een knoop of bestek wordt een concreet obstakel. Het acute venster verandert snel, dus wat daarin wordt toegevoegd vraagt een gerandomiseerde vergelijking en niet de indruk van één casus. In 2026 publiceerde Scientific Reports een gerandomiseerde studie van het NP Brain Hospital in Turkije, waarin Syrebo-robotondersteunde handtraining werd toegevoegd aan gewone neurodevelopmental therapy. Het artikel meldt grotere winst op handvaardigheid, tweehandige activiteiten en zelfzorg dan therapie alleen. De steekproef telt 30 mensen, en spasticiteit scheidde de groepen niet.",
        bg=[
            "De hand is moeilijk omdat zij kracht, gefractioneerde beweging en echt gebruik vraagt. Lopen kan als één doel worden geoefend; de hand moet grijpen en loslaten in een onstabiele houding. Neurodevelopmental therapy is al de basis van acute revalidatie, maar een therapeut kan niet elke greep onbeperkt herhalen, dus dosis en regelmaat zijn lastig op te rekken.",
            "Een zachte robotische handschoen kan die herhalingen in beginsel onder toezicht leveren. Acute patiënten veranderen nog. Of het apparaat veilig kan worden toegevoegd, en of functionele scores meebewegen, is een gecontroleerde vraag. Deze studie gaat over die fase, in plaats van een chronische studie te herhalen.",
        ],
        device="Het artikel noemt het apparaat een SYREBO robotic hand. De foto toont een zachte handschoen, een console en een tablet, zodat de lezer de vorm ziet. Modeldetails horen bij het artikel en het klinische protocol.",
        design="Gerandomiseerde vergelijking in één centrum. Eén groep kreeg robotondersteunde handtraining plus neurodevelopmental therapy (NT). De controlegroep kreeg alleen NT. De uitkomsten waren fijne handvaardigheid, tweehandige dagelijkse activiteiten en zelfzorg, niet kracht alleen.",
        sample="Het NP Brain Hospital includeerde 30 mensen in de acute fase en randomiseerde hen. Robotondersteunde sessies waren driemaal per week gedurende acht weken. Ook spasticiteitsmaten werden verzameld.",
        result="Het artikel meldt grotere verbeteringen in de robotondersteunde groep op de Nine-Hole Peg Test, de ABILHAND-vragenlijst en de Barthel-index. Dat is een verschil tussen groepen in deze steekproef. Het is geen beloofde herstelsnelheid. Spasticiteit liet geen significant verschil tussen groepen zien, dus niet elke maat liep uiteen.",
        sig=[
            "Het nuttige deel is het tijdstip: robotondersteunde oefening werd in de acute fase getest tegen lopende neurodevelopmental therapy, en niet geleend uit chronische resultaten. Drie functionele maten die samen bewegen, zeggen meer dan één score.",
            "Dertig gerandomiseerde patiënten dragen alleen een voorzichtige lezing. De studie beantwoordt langdurig thuisgebruik niet, en laat niet zien dat elk CVA-subtype hetzelfde pad volgt. De behandelend clinicus stelt het plan nog steeds vast.",
        ],
        limit="Kleine steekproef (n=30). Geen significant verschil tussen groepen voor spasticiteit. Scoreveranderingen zijn het verslag van de studie, geen individuele belofte.")

    add(2, "nl",
        title="Handfunctie na een CVA: een enkelblind RCT van een zachte robotische handschoen en spiegeltherapie, met follow-up na 6 maanden",
        desc="Journal of Rehabilitation Medicine, 2025: 49 deelnemers, zachte robotische handschoen versus spiegeltherapie, acht weken plus follow-up na zes maanden. De P-waarden tussen groepen zijn het verslag van het artikel.",
        lead="Spiegeltherapie gebruikt visuele input om de aangedane zijde te rekruteren. Een zachte robotische handschoen gebruikt meegaande aandrijving om openen en sluiten te herhalen. Welke verandering langer duurt, is niet te beantwoorden op de laatste trainingsdag. Een enkelblinde gerandomiseerde studie uit 2025 in het Journal of Rehabilitation Medicine vergeleek de twee benaderingen gedurende acht weken en volgde mensen tot zes maanden. Het artikel meldt statistisch significante verschillen tussen groepen ten gunste van de handschoen op de Box and Block Test, grijpkracht en FMA-UE aan het eind van de training, en meldt dat die winst van de handschoengroep na zes maanden nog aanwezig was.",
        bg=[
            "De vraag die telt na handtraining is of de verandering er nog is als mensen thuiskomen. Spiegeltherapie is eenvoudig en hangt af van aandacht voor de gespiegelde ledemaat. Een handschoen verlegt de herhaling naar een externe actuator, met een andere eis aan aandacht en uithouding. Beide zijn revalidatiemethoden. Dit is geen rangschikking van merken.",
            "Een score op de laatste trainingsdag kan een korte prikkel verwarren met een stabiele verandering. Een gerandomiseerde vergelijking met een bezoek na zes maanden maakt dat onderscheid mogelijk.",
        ],
        device="De foto in de rubriek toont een E12-opstelling voor spiegeltraining. Het studieapparaat is wat het artikel noemt; de foto is geen modelmatch.",
        design="Enkelblinde randomisatie van een zachte robotische handschoen tegen spiegeltherapie. Uitkomsten waren grijp-en-losvaardigheid (Box and Block), grijpkracht en beweging van de bovenste extremiteit (FMA-UE), met een bezoek zes maanden na de training.",
        sample="Negenenveertig mensen na een CVA werden gerandomiseerd. De training duurde acht weken. De registratie is NCT05898971.",
        result="Aan het eind van de training meldt het artikel verschillen tussen groepen ten gunste van de handschoen: Box and Block P=0,004, grijpkracht P=0,011, FMA-UE P=0,021. Na zes maanden was de winst van de handschoengroep nog aanwezig. Die P-waarden beschrijven deze steekproef. Zij kennen niet elke patiënt een herstelomvang toe.",
        sig=[
            "De extra informatie is tijd. Het verschil tussen groepen was bij het follow-upbezoek niet verdwenen. Dat is klinisch bruikbaarder dan een rangschikking op de laatste trainingsdag.",
            "Negenenveertig mensen is nog een kleine studie. Verschillen bij aanvang, de zijde van de laesie en oefenen na ontslag kunnen een score na zes maanden allemaal verschuiven. De bevinding hoort bij deze populatie en dit contrast.",
        ],
        limit="Kleine steekproef (n=49). P-waarden en behouden winst zijn het verslag van de studie, geen productbelofte.")

    add(3, "nl",
        title="Unilaterale neglect in de subacute fase: een gerandomiseerde vergelijking van robotische spiegeltraining op de SY-HRE12",
        desc="NeuroRehabilitation, 2025: 24 mensen in de subacute fase, allen met de SY-HRE12. Spiegelmodus versus vooraf ingestelde passieve beweging, 30 minuten, driemaal per week, vijf weken.",
        lead="Sommige mensen in de subacute fase hebben meer dan een zwakke hand. Zij kunnen ook één zijde van de ruimte verwaarlozen, en de stemming kan daaronder lijden. Robotische spiegeltraining beeldt de minder aangedane hand af op de aangedane hand, zodat zien en bewegen in dezelfde herhaling aankomen. Een gerandomiseerde studie uit 2025 in NeuroRehabilitation vergeleek twee manieren om dezelfde zachte handschoen te gebruiken: de spiegelfunctie en een vooraf ingestelde passieve modus. Het artikel meldt een voordeel van spiegeltraining op uitkomsten die met neglect en depressie samenhangen. De steekproef telt 24 mensen.",
        bg=[
            "Neglect maakt scores lastig te lezen. Het probleem is niet alleen dat de hand niet optilt; de aandacht voor één zijde van de ruimte is verminderd. Een gewone spiegel kan suggereren dat de aangedane hand beweegt terwijl dat niet zo is. Robotisch spiegelen probeert de aangedane handschoen met de andere hand te laten meebewegen, zodat zien en doen dezelfde trial vullen.",
            "Als de groepen verschillende apparaten hadden gebruikt, kon elk verschil het materiaal zijn. Deze studie gaf beide groepen de SY-HRE12 en veranderde alleen de modus. De vraag is hoe de handschoen werd aangedreven, niet of er een nieuwe machine was.",
        ],
        device="Het artikel gebruikte de SYREBO SY-HRE12. De foto toont een E12-console, een aangedreven handschoen en een spiegelhandschoen, zodat het systeem herkenbaar is. Het studieapparaat is de SY-HRE12.",
        design="Gerandomiseerde vergelijking. Beide groepen gebruikten de SY-HRE12. Eén groep gebruikte de spiegelfunctie. De andere gebruikte vooraf ingestelde passieve beweging. Uitkomsten omvatten unilaterale neglect, depressiegerelateerde maten en dagelijkse activiteiten.",
        sample="Vierentwintig mensen in de subacute fase, 12 in elke groep. Sessies duurden 30 minuten, driemaal per week, vijf weken.",
        result="In deze steekproef meldt het artikel een voordeel van robotische spiegeltraining boven vooraf ingestelde passieve beweging op neglect- en depressiegerelateerde uitkomsten. Dat is een verschil tussen twee modi van één apparaat. Het betekent niet dat de handschoen neglect of depressie behandelt. De controleconditie was geen gewone spiegelbox.",
        sig=[
            "De vraag verschuift van «of een handschoen wordt gebruikt» naar «welke modus van dezelfde handschoen». Voor mensen die ook neglect en stemmingslast hebben, is dat een preciezere klinische vraag.",
            "Vierentwintig deelnemers dragen alleen een voorzichtige lezing. De studie test thuisgebruik zonder toezicht niet, en biedt geen gegarandeerde verandering van aandacht of stemming.",
        ],
        limit="Kleine steekproef (12 per groep). De controlemodus was vooraf ingestelde passieve beweging, geen spiegelbox. Verschillen zijn het verslag van de studie.")

    add(4, "nl",
        title="Grijpkracht en motorscores na een CVA: een gerandomiseerde studie met robotische trainingshandschoenen",
        desc="SPORT TK, 2025: 30 deelnemers. Gemelde gemiddelde verschillen: grijpkracht 1,87 (95%-BI 0,39–3,35, P=0,015) en Fugl-Meyer 16,67 (95%-BI 3,9–29,4, P=0,012). Er wordt geen model genoemd.",
        lead="Na een CVA splitsen clinici de hand vaak in twee praktische problemen: of zij kan grijpen, en of zij gecontroleerd kan bewegen. Een gerandomiseerde studie uit 2025 in SPORT TK-EuroAmerican Journal of Sport Sciences mat beide. Het artikel meldt statistisch significante gemiddelde verschillen tussen groepen ten gunste van robotische trainingshandschoenen voor grijpkracht en voor de motorische Fugl-Meyer-score. Dertig mensen deden mee, en het artikel noemt geen commercieel model.",
        bg=[
            "Een verandering in grijpkracht levert niet vanzelf een bruikbare beweging op, en een hogere motorscore betekent niet dat iemand een kopje kan optillen. Kracht en beweging in dezelfde gerandomiseerde vergelijking meten voorkomt dat alleen de vriendelijkste van de twee wordt gepubliceerd.",
            "Artikelen over handschoenen laten het model vaak weg. Zonder model kan een resultaat niet op een productspecificatie worden gekopieerd. Deze samenvatting blijft daarom bij de contrasten die het artikel werkelijk geeft.",
        ],
        device="",
        design="Gerandomiseerde vergelijking van oefenen met een robotische trainingshandschoen tegen een controleconditie. Gedeelde uitkomsten waren grijpkracht en de motorische Fugl-Meyer-score, gerapporteerd als gemiddelde verschillen met 95%-betrouwbaarheidsintervallen.",
        sample="Dertig mensen na een CVA, 15 in elke groep. Het artikel identificeert geen op de markt gebracht model. De generieke foto van de handschoen is een illustratie, geen identificatie van het apparaat.",
        result="De gemelde gemiddelde verschillen tussen groepen zijn grijpkracht 1,87 (95%-BI 0,39 tot 3,35, P=0,015) en Fugl-Meyer 16,67 (95%-BI 3,9 tot 29,4, P=0,012). Een gemiddeld verschil is niet de winst van elke persoon. Het interval van de motorscore is breed, en dat is hoe een kleine steekproef eruitziet als de schatting onnauwkeurig is.",
        sig=[
            "Zowel het verschil als het interval publiceren is bruikbaarder dan de zin «beter dan controle». De richting is zichtbaar, en de onzekerheid ook.",
            "Omdat geen model wordt genoemd, kan het resultaat niet worden naverteld als specificatie of indicatie van een bepaalde Syrebo-handschoen. Dertig mensen laten ook ruimte voor steekproefruis.",
        ],
        limit="Kleine steekproef (n=30). Geen model geïdentificeerd, en de foto is geen match. Gemiddelde verschillen en P-waarden zijn de statistiek van de studie.")

    add(5, "nl",
        title="Handfunctie in de vroege subacute fase: een enkelblinde pilot-RCT van de SY-HR03E door het Huashan-team",
        desc="Enkelblinde pilot-RCT in BioMedical Engineering OnLine: 20 opgenomen patiënten, SY-HR03E, vier weken. Het artikel meldt volledige afronding, geen bijwerkingen en voorlopige signalen op handscores en dagelijkse activiteiten.",
        lead="In de vroege subacute fase is de eerste vraag niet hoeveel punten een score zou kunnen stijgen. De vraag is of de sessies kunnen worden afgemaakt, en of zij veilig zijn. Een team onder leiding van professor Jia Jie in het Huashan Hospital van Fudan University publiceerde in BioMedical Engineering OnLine een enkelblinde gerandomiseerde pilot over de Syrebo SY-HR03E voor handrevalidatie in dat venster. Het artikel meldt dat alle 20 deelnemers vier weken afrondden, zonder uitval en zonder bijwerkingen. Handscores verbeterden in beide groepen, met een grotere verandering in de handschoengroep. Een verandering binnen de groep op dagelijkse activiteiten bereikte statistische significantie in de handschoengroep.",
        bg=[
            "Arm en hand herstellen meestal later dan lopen. Eten, aankleden en wassen hangen af van gefractioneerde vingerbeweging, niet van één krachtgetal. Gewone handtherapie helpt, maar het aantal herhalingen dat een therapeut kan geven is beperkt, en dezelfde beweging is aan het bed lastig te herhalen.",
            "Een pneumatische handschoen kan de vingers buigen en strekken met weinig massa op de hand, en daarom wordt gebruik aan het bed besproken. Mensen in de vroege subacute fase herstellen ook spontaan. Elk «voorlopig effect» moet tegen die achtergrond worden gelezen. Een gerandomiseerde pilot laat zien dat een protocol haalbaar is en laat een signaal achter voor een grotere studie. Zij vervangt geen bevestigende studie.",
        ],
        device="Het artikel beschrijft de SY-HR03E als een commerciële zachte handschoen plus een tafelcontroller. De gemelde massa is ongeveer 3,5 kg voor het systeem en ongeveer 110 g voor de handschoen. Pneumatische balgen op de rug van de hand ondersteunen flexie en extensie. Druksensoren volgen de verandering als de persoon probeert te bewegen; boven een vooraf ingestelde drempel van 0,7 kPa behandelt de controller die verandering als bewegingsintentie en pompt op of leeg. De bedoelde modus is actieve assistentie, niet een volledig passieve trek.",
        design="Enkelblinde pilotrandomisatie. De robotgroep voegde handschoenondersteund openen en sluiten toe aan standaardrevalidatie. De conventionele groep kreeg traditionele handtherapie van dezelfde sessieduur. Beide groepen kregen ook één uur per dag standaardrevalidatie. Een therapeut hield de houding in de gaten. Register: ChiCTR2000034614.",
        sample="Twintig opgenomen patiënten, 7 dagen tot 3 maanden na het begin, 10 in elke groep. Handschoensessies duurden 30 minuten per dag, vijf dagen per week, vier weken. Elke open-dichtbeweging werd ongeveer drie seconden vastgehouden. Auteursaffiliaties omvatten het klinische team en, zoals het artikel vermeldt, Shanghai Siyi Intelligent Technology. Die relatie hoort bij het lezen.",
        result="Het artikel meldt dat alle 20 mensen vier weken voltooiden, zonder uitval en zonder bijwerkingen. Fugl-Meyer-scores van de hand verbeterden in beide groepen, met een grotere verbetering in de robotgroep. Op de modified Barthel Index wordt alleen de verandering binnen de robotgroep als statistisch significant gemeld (p<0,001); de verandering binnen de conventionele groep niet. Het Brunnstrom-stadium van de hand liet eveneens alleen in de robotgroep een significante verandering binnen de groep zien. In een pilot van 10 tegen 10 is een P-waarde binnen de groep een signaal, geen bewijs dat de dagelijkse functie bij patiënten in het algemeen zal stijgen.",
        sig=[
            "Veel studies met zachte handschoenen includeren mensen in de chronische fase. Deze pilot verplaatst de vraag naar haalbaarheid en veiligheid naar het venster van 7 dagen tot 3 maanden. Zij schuift geen claims over werkzaamheid uit de chronische fase naar voren.",
            "Handscores en scores voor dagelijkse activiteit kregen niet dezelfde statistische vorm: het artikel meldt een significante Barthel-verandering binnen de groep alleen in de handschoengroep. Die splitsing is het waard om opnieuw te testen. Het is geen uitspraak dat activiteiten van het dagelijks leven zijn opgelost. Een handschoen van 110 g en intentiedetectie maken een gesprek over gebruik aan het bed en later thuis mogelijk. Deze studie zelf werd bij opgenomen patiënten gedaan.",
        ],
        limit="Pilotrandomisatie, 10 per groep. Voorlopige signalen vragen een grotere steekproef. De P-waarde is het verslag van het artikel voor die uitkomst. Een apparaatgerelateerde affiliatie is vermeld en moet worden meegewogen.")

    add(6, "nl",
        title="Handbeperking bij een flegma-stasepatroon: een vierarmige studie met 200 mensen naar een handschoen plus elektroacupunctuur",
        desc="Journal of Hunan University of Chinese Medicine: 200 deelnemers, vier armen. De gemelde totale effectiviteitspercentages waren 88%, 76%, 77,6% en 70,8%. Die cijfers zijn de samengestelde maat van de studie, geen productpercentage.",
        lead="Een robotische handschoen en elektroacupunctuur in één plan zetten is een concrete integratieve keuze, en het resultaat moet aan de arm blijven hangen die het voortbracht. Een vierarmige studie uit 2022 in het Journal of Hunan University of Chinese Medicine includeerde 200 mensen met handbeperking na een CVA in het patroon phlegm-stasis blocking collaterals, en vergeleek handschoen plus elektroacupunctuur, alleen de handschoen, alleen elektroacupunctuur en gewone revalidatie. De eigen «totale effectiviteitspercentages» van het artikel zijn 88%, 76%, 77,6% en 70,8%. Die samenstelling is de samenvatting van de auteurs. Het is geen werkzaamheidspercentage van een product.",
        bg=[
            "Onder deze patroondiagnose combineren trajecten vaak moderne revalidatie met elektroacupunctuur. Een opzet met vier armen kan combinatie, apparaat alleen, acupunctuur alleen en gewone zorg op één schaal laten zien, in plaats van een voor-naverhaal zonder contrast.",
            "Een totaal effectiviteitspercentage vouwt meerdere oordelen samen tot één percentage. Het is bruikbaar voor een grof contrast en onbruikbaar als de verandering van één persoon op een genoemde schaal. Het kan niet worden geciteerd als «de werkzaamheid van de handschoen is 88%».",
        ],
        device="",
        design="Vier armen: robotische handschoen plus elektroacupunctuur, alleen de handschoen, alleen elektroacupunctuur, en gewone revalidatie. De uitkomst die hier wordt besproken is het totale effectiviteitspercentage van het artikel. Auteursaffiliaties omvatten Shanghai Siyi Intelligent Technology, met Yin Ganggang als medeuteur. Die vermelding blijft bij het lezen.",
        sample="Tweehonderd mensen met handbeperking na een CVA in het patroon phlegm-stasis blocking collaterals. Dit is de grootste steekproef in de rubriek. Het artikel noemt geen model dat aan een huidig product kan worden gekoppeld, en de generieke foto is zo’n koppeling niet.",
        result="De gemelde totale effectiviteitspercentages zijn 88% voor handschoen plus elektroacupunctuur, 76% voor alleen de handschoen, 77,6% voor alleen elektroacupunctuur en 70,8% voor gewone revalidatie. Een hogere samenstelling in de gecombineerde arm betekent alleen dat die arm onder de regel van deze studie hoger scoorde. Het kent 88% niet aan de handschoen toe, en 76% is geen productpercentage. De cijfers van alleen de handschoen en alleen elektroacupunctuur liggen dicht bij elkaar, wat ook pleit tegen het hele patroon door één component te verklaren.",
        sig=[
            "Tweehonderd mensen en vier armen geven een vergelijkbare samenstelling, geen percentage voor een productpagina. Gelezen als totaal effectiviteitspercentage zijn de verschillen tussen combinatie, losse modaliteiten en gewone zorg beperkt.",
            "Het artikel, zoals het hier is samengevat, levert niet dezelfde gemiddelde verschillen als de andere studies in de rubriek. Tot die schalen op tafel liggen, gaat de studie over hoe de onderdelen werden gecombineerd, niet over hoeveel punten een handscore zal stijgen.",
        ],
        limit="De percentages zijn de eigen totale effectiviteitspercentages van de studie. De gecombineerde arm kan niet aan de handschoen of aan elektroacupunctuur alleen worden toegeschreven. Er wordt geen model genoemd.")

    add(7, "nl",
        title="Handrevalidatie na een infarct in het stroomgebied van de arteria cerebri media: een casus van een 66-jarige patiënt",
        desc="Casus in Cureus: een 66-jarige vrouw met een bilateraal infarct in het ACM-stroomgebied kreeg een Syrebo-handschoenprogramma onder klinisch toezicht. Eén casus is geen algemeen resultaat.",
        lead="Een gerandomiseerde studie beschrijft een gemiddeld verschil. Een casus beschrijft hoe revalidatie voor één persoon werd ingericht. In 2024 meldden Sharma en collega’s in Cureus een 66-jarige vrouw met een infarct in de stroomgebieden van de arteria cerebri media, die neurofysiotherapie kreeg rond een Syrebo-handschoenprogramma. Het verslag volgt het verloop van observatie en functionele verandering. Het is één casus, en die generaliseert niet.",
        bg=[
            "Een infarct in dit stroomgebied treft vaak arm en hand samen met taal of cognitie, dus het plan is meer dan een zwakke hand. Families willen meestal weten wanneer oefenen met de handschoen in de fysiotherapie zat, en wie toezicht hield, meer dan een percentage.",
            "Een casus kan die volgorde opschrijven. Er is geen parallelle controle, dus elke voor-naverandering mengt spontaan herstel, gewone zorg en de handschoen. Die stukken zijn niet te scheiden.",
        ],
        device="Het artikel bespreekt een Syrebo-handschoenprogramma en noemt geen model. De foto van handschoen en console is figuur 2 van dat open-accessverslag (CC BY 4.0), getoond in het fragment bovenaan. Het is geen figuur uit een andere review.",
        design="Verslag van één casus, geen gerandomiseerde studie. Nadat de persoon medisch stabiel was, gaven clinici neurofysiotherapie waarin het Syrebo-handschoenprogramma was opgenomen.",
        sample="Een 66-jarige vrouw met een bilateraal infarct in het ACM-stroomgebied. Het verslag legt observaties en functionele verandering vast. Het levert geen statistiek tussen groepen.",
        result="De waarde van het verslag is het zorgverloop, niet een verbeteringspercentage. Het laat zien hoe een zachte handschoen in de revalidatie van één persoon met een ernstig infarct werd geplaatst, onder professioneel toezicht. Een verandering in één casus is geen beloofde mate van herstel.",
        sig=[
            "In een rubriek die vooral uit gerandomiseerde studies bestaat, staat één casus hier om te laten zien hoe een programma bij een persoon werd gebruikt. Het vult een verhalende leemte. Het verhoogt het bewijsniveau niet.",
            "Eén casus kan niet schatten hoe vaak bijwerkingen voorkomen, en kan niet zeggen of de acute, subacute of chronische fase beter past. Die vragen blijven bij gecontroleerde studies.",
        ],
        limit="Enkele casus. Geen algemeen effect. Functionele verandering kan niet aan de handschoen alleen worden toegekend.")

    add(8, "nl",
        title="Beperking van de bovenste extremiteit na een CVA: een gerandomiseerde studie met 60 mensen naar innovatieve spiegeltherapie",
        desc="New Medicine, 2024: 60 mensen, vier weken. Het artikel meldt grotere winst op FMA-UE, FMA-WH en de modified Barthel Index met innovatieve spiegeltherapie dan met conventionele spiegeltherapie.",
        lead="Conventionele spiegeltherapie gebruikt een spiegel om te suggereren dat de aangedane hand beweegt. De innovatieve versie vraagt een robotische handschoen de aangedane hand door dezelfde handeling te voeren die de spiegel toont, zodat zien en doen de sessie delen. In 2024 publiceerde New Medicine een gerandomiseerde studie van Chen en collega’s die de twee versies bij 60 mensen gedurende vier weken vergeleek. Het artikel meldt grotere winst voor innovatieve spiegeltherapie op beweging van de bovenste extremiteit, pols-handbeweging en dagelijkse activiteiten.",
        bg=[
            "Spiegeltherapie heeft een bekende grens: als de aangedane hand niet beweegt, heeft de visuele suggestie geen gekoppelde motorische input. Geassisteerde flexie en extensie aan de spiegeltaak koppelen is een poging de aangedane zijde een beweging echt te laten voltooien binnen een bereik dat de therapeut vaststelt.",
            "Of die verandering op scores verschijnt, moet worden getest tegen conventionele spiegeltherapie, niet tegen niets doen. Zestig mensen, gelijk verdeeld, is een voorlopige gerandomiseerde omvang.",
        ],
        device="Een trainingsafbeelding op de tijdschriftpagina toont een Yisheng-merk (羿生). De rubriek koppelt dat merk aan de SY-HR08E in officiële materialen en toont een productfoto met scherm, console en handschoen. De koppeling is een identificatienotitie, geen modelclaim die als studieregistratie is gedrukt.",
        design="Toewijzing met toevalsgetallen. Innovatieve spiegeltherapie, een spiegeltaak gecombineerd met een robotische handschoen, werd vergeleken met conventionele spiegeltherapie. Uitkomsten omvatten FMA-UE, FMA-WH en de modified Barthel Index.",
        sample="Zestig mensen met een beperking van de bovenste extremiteit na een CVA, 30 in elke groep, gedurende vier weken.",
        result="Het artikel meldt grotere verbetering voor innovatieve spiegeltherapie op FMA-UE, FMA-WH en de modified Barthel Index. Dat is de beschrijving tussen groepen van de studie. Gemiddelden en P-waarden worden op deze pagina niet herberekend; zolang de tijdschriftpagina nog wordt nagekeken, blijven die cijfers bij het artikel.",
        sig=[
            "De vraag is of het toevoegen van een geassisteerde beweging die bij de spiegel past de scores verandert ten opzichte van de spiegel alleen. Zestig mensen leveren een voorlopig contrast, geen bewijs voor een thuisprogramma.",
            "De tijdschriftfoto aan de SY-HR08E koppelen helpt de lezer alleen het apparaat te herkennen. Of het scoreverschil stabiel is, wacht op een onafhankelijke controle van de volledige cijfers.",
        ],
        limit="Dertig mensen per groep. Verschillen volgen het artikel. Gemiddelden en P-waarden worden hier niet herberekend. De modelkoppeling is een controle tussen de tijdschriftfiguur en officiële materialen.")

    add(9, "nl",
        title="Linkszijdige hemiparese na een ACM-infarct: één verslag van faradische stimulatie plus een robotische hand",
        desc="Casus in IJPRCP: een 60-jarige man met linkszijdige hemiparese begon ongeveer drie maanden na het CVA met faradische stimulatie plus de Syrebo C12, vijfmaal per week gedurende vier weken. Eén gecombineerde casus wordt aan geen van beide onderdelen toegekend.",
        lead="Een hemiparetische hand krijgt soms twee inputs tegelijk: elektrische stimulatie gericht op de spier, en een robotische hand om de vingers te openen en te sluiten. Een casus uit 2025 in het International Journal of Physiotherapy Research and Clinical Practice legt vier weken faradische stimulatie plus een Syrebo C12 vast bij één man met linkszijdige hemiparese. Het is het verslag van een gecombineerd plan, geen werkzaamheidsstudie van een van beide onderdelen.",
        bg=[
            "Maanden na een CVA is verandering van de hand meestal trager, en clinici voegen soms stimulatie of externe hulp toe aan gewone oefening. Zodra beide worden gebruikt, kan een voor-naverandering niet schoon aan een van beide worden gegeven.",
            "Het verslag blijft nuttig. Het zegt wanneer het plan begon, hoe vaak het liep en welk apparaat in de kamer stond. Het geeft geen percentage, en het geeft geen verschil tegen een controle.",
        ],
        device="Het robotische apparaat in het verslag is de Syrebo C12. De foto is een uitsnede van de officiële C12-productpagina, zodat console en handschoen herkenbaar zijn. Zij voegt geen specificaties toe die het artikel wegliet.",
        design="Eén gecombineerde interventie: faradische stimulatie samen met oefenen met de robotische hand Syrebo C12. Er is geen parallelle controlegroep.",
        sample="Een 60-jarige man met linkszijdige hemiparese. Het plan begon 3 maanden en 2 weken na het CVA, vijfmaal per week, gedurende vier weken.",
        result="Deze pagina herdrukt geen functionele scores die voor de rubriek niet tegen het artikel zijn gecontroleerd. Wat duidelijk is, is de inrichting: stimulatie en robotisch oefenen werden samen gebruikt, dus een verandering kan niet worden geschreven als het effect van de C12 alleen of van stimulatie alleen.",
        sig=[
            "Het verslag voegt een concrete planning toe: ongeveer drie maanden na het CVA, vijf sessies per week, twee modaliteiten samen. Het verhoogt het bewijsniveau niet.",
            "Eén casus van linkszijdige hemiparese na een ACM-infarct staat niet voor andere laesies of andere tijden na het begin.",
        ],
        limit="Eén gecombineerde casus. De verandering wordt niet aan de C12 of aan stimulatie toegekend, en het is geen algemeen effect.")

    add(10, "nl",
        title="Een zachte pols-handorthese: ontwerp en voorlopige evaluatie in Wearable Technologies",
        desc="Ledoux en Barth beschrijven hun eigen 3D-geprinte pols-handorthese in Wearable Technologies. Deze notitie blijft bij dat ontwerpartikel. Zij rangschikt geen commerciële producten en is geen werkzaamheidsstudie.",
        lead="In 2024 publiceerde Wearable Technologies, van Cambridge University Press, een ontwerpartikel van Ledoux en Barth aan Vanderbilt University. Het apparaat dat zij bouwden en voorlopig evalueerden is hun eigen 3D-geprinte pols-handgrijporthese. Het artikel noemt commerciële zachte structuren terwijl het draagbare handen bespreekt. Deze rubriek maakt van die bespreking geen rangschikking, en behandelt het artikel niet als werkzaamheidsbewijs voor Syrebo.",
        bg=[
            "Een handapparaat dat de therapieruimte verlaat moet antwoord geven op gewicht, profiel en of iemand het kan aandoen. Ontwerpartikelen noemen die beperkingen meestal eerst en beschrijven dan een prototype. Zij rapporteren niet eerst een multicentrische functionele studie. Een ontwerpartikel als werkzaamheidsartikel lezen verzint klinische eindpunten die niet zijn gemeten.",
            "Een zachte structuur en een rigide exoskelet beantwoorden verschillende technische vragen. Zachtheid is één manier om het profiel te verkleinen. Over functionele verandering praten vraagt nog een eigen studie bij mensen.",
        ],
        device="Het fragment bovenaan is de open-access eerste pagina (CC BY 4.0), geen vergelijkingstabel. De productfoto toont een klinisch Syrebo-handschoensysteem. Het is geen figuur uit dit experiment.",
        design="Ontwerp, modellering en voorlopige evaluatie van de eigen 3D-geprinte orthese van de auteurs. Het artikel is geen gerandomiseerde studie van Syrebo en geen werkzaamheidsvergelijking tussen op de markt gebrachte apparaten.",
        sample="Het menselijke deel is een voorlopige blik op het prototype van de auteurs. Omvang en taken zijn die van het artikel. Het wordt hier niet herschreven als een Syrebo-cohort.",
        result="Deze pagina citeert geen commerciële bijvoeglijke naamwoorden en noemt geen andere merken. Wat overblijft is dat het artikel een open-access ontwerpstudie is over een zachte, draagbare structuur. Het woord «presumably» van de auteurs markeert comfort als iets dat zij niet als gemeten eindpunt behandelden.",
        sig=[
            "Het artikel staat in de rubriek zodat een ontwerpstudie onderscheiden blijft van een werkzaamheidsstudie. Of een zachte structuur een apparaat in het dagelijks leven makkelijker draagbaar maakt, is een draagstudie en een functionele studie, apart.",
            "Open access laat een lezer de formulering controleren. Het punt van controleren is een vermoeden geen conclusie te laten worden, niet een lichtste product te kiezen.",
        ],
        limit="Geen werkzaamheidsstudie van Syrebo, en geen productrangschikking. De bron relativeert comfort met «presumably». De uitsnede van de eerste pagina bevat geen vergelijkingstabel.")

    add(11, "nl",
        title="Vingerrobots bedoeld voor thuisgebruik: een ontwikkelnotitie in het Journal of the Robotics Society of Japan",
        desc="Een artikel uit 2023 in het Journal of the Robotics Society of Japan bespreekt vingerrobots voor thuisgebruik bij hemiparese en noemt Syrebo onder de weinige gecommercialiseerde voorbeelden. Het is geen klinische studie.",
        lead="Handrevalidatie thuis wordt al jaren besproken. Gecommercialiseerde voorbeelden in de verenigingsliteratuur zijn nog schaars. In 2023 publiceerde het Journal of the Robotics Society of Japan een artikel van Furudate en collega’s over een vingerrevalidatierobot bedoeld voor thuisgebruik na hemiparese, en over de ontwikkeling daarvan met clinici. De auteurs merken op dat gecommercialiseerde gevallen voor thuisgebruik zeldzaam blijven, en zij noemen de Syrebo-handhandschoen als zo’n geval. Het artikel is een notitie over ontwikkeling en samenwerking, geen werkzaamheidsstudie.",
        bg=[
            "Tussen de afdeling en thuis zitten aantrekken, veiligheidsgrenzen en gebruik als er geen therapeut in de kamer is. Technische artikelen plaatsen die beperkingen in het werk met clinici. Genoemd worden betekent dat de auteurs dit product als voorbeeld kozen. Het betekent niet dat de vereniging een gecontroleerde studie deed.",
            "«Weinigen zijn gecommercialiseerd» is ook een grens. Het lezen als «thuisrevalidatie is al algemeen beschikbaar» maakt van een voorbeeld een epidemiologische claim.",
        ],
        device="Het artikel drukt geen foto van de handschoen af. Het beeld van handschoen en console in deze rubriek is figuur 2 van de Cureus-casus uit 2024 van Sharma en collega’s (CC BY 4.0). Het bijschrift zegt dat. Het is niet de oorspronkelijke figuur van het Japanse verenigingsartikel.",
        design="Een ontwikkelingsartikel in een verenigingstijdschrift over vingerrobots voor thuisgebruik en over samenwerken met clinici. Er is geen randomisatie en geen functionele vergelijking tussen groepen.",
        sample="Een klinische steekproefgrootte is niet van toepassing. Het artikel bespreekt een pad naar een product, niet uitkomsten in een cohort.",
        result="De uitspraak, zoals zij hier wordt gebruikt, is dat gecommercialiseerde vingerrobots gericht op thuis nog schaars zijn, en dat Syrebo één voorbeeld is dat de auteurs noemen. De rubriek houdt die reikwijdte. Zij wordt niet herschreven als werkzaamheid, als een marktrang of als de belofte dat training thuis zal worden afgemaakt.",
        sig=[
            "De waarde van de notitie is dat thuisgebruik wordt behandeld als een technisch probleem dat met clinici wordt gedefinieerd. Een gecommercialiseerd voorbeeld laat zien dat één apparaat van prototype naar product ging.",
            "Of het thuis veilig en herhaald kan worden gebruikt, hangt nog af van indicatie, toezicht en aparte klinische studies. Het verenigingsartikel levert die gegevens niet.",
        ],
        limit="Geen klinische studie van Syrebo. De bron benadrukt dat gecommercialiseerde voorbeelden schaars blijven. De foto komt uit een andere open-accesscasus.")
